"""Freeze HI gate outcomes without adjusting either candidate."""
import json
from pathlib import Path
import numpy as np,pandas as pd
HERE=Path(__file__).resolve().parent;OUT=HERE/'outputs/HI'
def main():
    b=pd.read_csv(HERE/'benchmarks/HI/cis_household_deciles_2022.csv').set_index('decile');rec=pd.read_csv(HERE/'benchmarks/HI/cis_recipients_2022.csv').set_index('decile');frames=[];quarterly=[]
    national=[]
    for arm in ['HI_baseline_audit','HI_cis_gate']:
        directory=OUT/'runs'/f'F_CFC_{arm}_q2_s0';x=pd.read_csv(directory/'CIS_deciles.csv');f=x[x.quarter==0].set_index('decile');z=f.copy();z['arm']=arm;z['CIS_share']=b.share;z['relative_share_gap']=f.share/b.share-1;z['CIS_per_HH']=b.per_HH;z['model_gov_share']=f.government_transfers/f.government_transfers.sum();z['CIS_gov_share']=b.government_transfers/b.government_transfers.sum();z['gov_share_gap']=z.model_gov_share/z.CIS_gov_share-1;z['model_recipient_share']=f.government_recipients/f.weight;z['CIS_recipient_share']=rec.government_recipient_share;z['taxes_expected_total']=f.taxes+(f.self_employment+f.investment+f.private_pensions)*.1736097674817538/(1-.1736097674817538)
        frames.append(z.reset_index());national.append(dict(arm=arm,model_DI=f.cash_DI.sum(),CIS_comparable_cash_income=f.income.sum(),households=f.weight.sum(),maximum_relative_share_error=z.relative_share_gap.abs().max(),maximum_transfer_share_error=z.gov_share_gap.abs().max(),maximum_recipient_gap_pp=100*(z.model_recipient_share-z.CIS_recipient_share).abs().max()))
        q=pd.read_csv(directory/'outcomes.csv');a=q.groupby('quarter').sum(numeric_only=True);a['constrained_share']=a.constrained_households/a.represented_households;a['cash_saving_rate']=1-a.consumption/a.cash_DI;a['arm']=arm;quarterly.append(a.reset_index())
    f=pd.concat(frames);f.to_csv(OUT/'CIS_t0_gate_comparison.csv',index=False);n=pd.DataFrame(national);n.to_csv(OUT/'CIS_national_comparison.csv',index=False);pd.concat(quarterly).to_csv(OUT/'two_quarter_outcomes.csv',index=False)
    base=n[n.arm=='HI_baseline_audit'].iloc[0];candidate=n[n.arm=='HI_cis_gate'].iloc[0];change=candidate.model_DI/base.model_DI-1
    gfcf=json.loads((OUT/'gfcf_build_provenance.json').read_text());GDP=pd.read_csv(OUT/'gfcf_GDP_initialization.csv');stocks=json.loads((OUT/'cis_allocation_provenance.json').read_text())
    mapping=pd.read_csv(HERE/'outputs/IH/observed_investment_concordance.csv');actual=pd.read_csv(OUT/'gfcf_build.csv').groupby(['region','industry'])[['new_investment','observed_allocation']].sum().reset_index().rename(columns={'industry':'industry_code'});mapped=mapping.merge(actual,on=['region','industry_code']);mapped['actual_group_component']=mapped.allocated_observed_investment*mapped.new_investment/mapped.observed_allocation.clip(lower=1e-30);group=mapped.groupby(['region','source_group'])[['allocated_observed_investment','actual_group_component']].sum();group['relative_error']=(group.actual_group_component/group.allocated_observed_investment.clip(lower=1e-30)-1).where(group.allocated_observed_investment>0,0.);group.reset_index().to_csv(OUT/'gfcf_mapped_group_check.csv',index=False);group_error=float(group.relative_error.abs().max())
    gates=dict(HI_G1=dict(passed=True,evidence='Adapter source already differs from CIS; retained population widens divergence; exact before/after D2 and matched payroll snapshots retained. Intermediate historical raw fit states were not archived; code evidence and retained outputs distinguish this limitation.'),HI_G2=dict(passed=bool(candidate.maximum_relative_share_error<=.1 and abs(change)<=.005),max_relative_share_error=float(candidate.maximum_relative_share_error),national_DI_change=float(change)),HI_G3=dict(passed=bool(candidate.maximum_transfer_share_error<=.1),max_relative_transfer_amount_share_gap=float(candidate.maximum_transfer_share_error),max_recipient_rate_difference_pp=float(candidate.maximum_recipient_gap_pp),definition='Amounts assessed against same 10% relative distribution tolerance as HI-G2. Recipient rates reported directly; recipient incidence is close, amounts fail.'),HI_G4=dict(stock_marginals_exact=stocks['stock_columns_exact'],regional_income_budgets_exact=stocks['all_regional_component_totals_exact'],accounting_error=json.loads((OUT/'runs/F_CFC_HI_cis_gate_q2_s0/manifest.json').read_text())['max_accounting_error'],income_ranked_wealth_shares='reported separately; changing income ranks moves this joint distribution, never silently refitted.'),HI_G5=dict(passed=bool(group_error<=.02 and abs(gfcf['national_relative_gap'])<=.005 and GDP.passed.all()),max_model_industry_relative_allocation_error=gfcf['group_max_relative_error'],max_source_mapped_group_relative_allocation_error=group_error,national_relative_gap=gfcf['national_relative_gap'],national_level_passed=bool(abs(gfcf['national_relative_gap'])<=.005),unallocated_annual=gfcf['unallocated_annual'],regions_failing_GDP=int((~GDP.passed).sum()),national_expenditure_gap=float(GDP.expenditure_gap.sum())),STEP4=dict(started=False,reason='Neither input passes its adoption gates. No combined build, F_CFC/E2 12-quarter runs, or empirical E2 retest. IH all-seed historical results remain references.'))
    assert not gates['HI_G2']['passed'] and not gates['HI_G5']['passed']
