    r=pd.read_csv(OUT/'gfcf_build.csv');r['old_net']=r.old_investment-r.CFC;r['new_net']=r.new_investment-r.CFC;r['change']=r.new_investment-r.old_investment;r.to_csv(OUT/'investment_industry_province.csv',index=False);r.groupby('industry')[['old_investment','new_investment','observed_allocation','unallocated','CFC','old_net','new_net','change']].sum().mul(4/1e9).reset_index().to_csv(OUT/'investment_industry_annual_B.csv',index=False)
    wealth=[]
    for arm,z in f.groupby('arm'):
        z=z.copy();z['quintile']=np.ceil(z.decile/2).astype(int);a=z.groupby('quintile')[['deposits','mortgages','net_worth']].sum();a['net_worth_share']=a.net_worth/a.net_worth.sum();a['arm']=arm;wealth.append(a.reset_index())
